INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:accountant',true,'CPA License # (State Abbreviation)',ARRAY['State Board of Accountancy (jurisdiction-specific, e.g., California Board of Accountancy, New York State Board of Public Accountancy)','American Institute of CPAs (AICPA) — professional standards','National Association of State Boards of Accountancy (NASBA) — CPAverify and CPE standards','Internal Revenue Service (IRS) — Enrolled Agent authorization and PTIN registry','IRS Office of Professional Responsibility — Circular 230 compliance for tax practitioners']::text[],ARRAY['guaranteed tax refund','we will eliminate your tax debt','we guarantee IRS audit protection','maximum refund guaranteed','we can settle your taxes for pennies on the dollar','no taxes owed — guaranteed','IRS-approved tax strategy']::text[],ARRAY['Results may vary. Past tax savings do not guarantee future outcomes.','Tax advice provided is based on information supplied by the client and current tax law, which is subject to change.','This firm is required to comply with IRS Circular 230. Nothing herein constitutes a covered opinion under Circular 230.','CPA license status should be verified through your state board of accountancy or NASBA CPAverify.','Enrolled Agent status should be verified through the IRS EA roster.']::text[],false,false,true,ARRAY['Advertising claims of specific tax savings amounts must be substantiated and not misleading under AICPA Code of Professional Conduct Rule 502','CPA licensees may not make false, misleading, or deceptive claims in advertising under state board of accountancy rules','Use of ''CPA,'' ''Certified Public Accountant,'' or ''EA'' designations requires active licensure in the applicable jurisdiction','Fee claims such as ''lowest prices'' require substantiation','Testimonials must not imply guaranteed results or outcomes atypical of the average client experience','Comparative advertising against named competitors must be factually accurate and not disparaging under AICPA ethics standards']::text[])
