INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:dentist',true,'State Dental License #',ARRAY['State Dental Board (jurisdiction-specific, e.g. California Dental Board, Texas State Board of Dental Examiners)','American Dental Association (professional standards)','Drug Enforcement Administration (DEA) for controlled substance prescribing','State Department of Health (infection control and facility standards)','Centers for Medicare and Medicaid Services (CMS) for Medicaid billing','OSHA (occupational safety in dental settings)']::text[],ARRAY['guaranteed results','pain-free guaranteed','best dentist in [city]','#1 dentist','cure','permanent whitening','same-day implants always available','we accept all insurance']::text[],ARRAY['Individual results may vary. Cosmetic outcomes depend on patient-specific oral health conditions.','Sedation dentistry carries risks; a thorough medical history review is required prior to sedation services.','Dental implant candidacy requires a clinical examination and may not be appropriate for all patients.','This information is educational and does not constitute dental advice. Consult a licensed dentist for personalized care.','Financing through third-party providers such as CareCredit is subject to credit approval and lender terms.']::text[],false,true,false,ARRAY['FTC endorsement guidelines require patient testimonials to reflect typical results or include a disclaimer','Before-and-after photos require patient consent and must not be misleadingly edited','Claims of specialty status (e.g. orthodontist, oral surgeon) require completion of an accredited post-doctoral specialty program','State dental board advertising rules prohibit false, deceptive, or misleading statements about services or fees','Discount or promotional offers must clearly state all terms and exclusions']::text[])
