INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:hair_salon',true,'State Cosmetology Establishment License #',ARRAY['State Board of Cosmetology (varies by state, e.g. California Board of Barbering and Cosmetology, Texas Department of Licensing and Regulation)','Local Health Department (county or municipal salon permit authority)']::text[],ARRAY['guaranteed results','permanent hair restoration','medically proven','dermatologist tested and certified','fixes hair loss','FDA approved treatment']::text[],ARRAY['Individual results may vary','Chemical services may cause allergic reactions; patch test recommended 48 hours prior','Prices subject to change based on hair length and density','Not responsible for results when client has previously used box dye or undisclosed chemical treatments']::text[],false,false,false,ARRAY['Cannot claim medical or therapeutic efficacy for hair treatments without substantiation','Cannot use before/after photos without client consent','Must disclose any sponsored or paid product endorsements','Cannot guarantee specific color outcomes in advertising']::text[])
