INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:hardware_store',false,NULL,ARRAY['Local municipality business licensing authority','State sales tax authority']::text[],ARRAY['Licensed electrician services','Licensed plumbing contractor','We are certified contractors','Professional installation included','We guarantee permits will be approved']::text[],ARRAY['Tool rental terms and conditions apply; customer responsible for damage','Propane exchange subject to tank inspection; damaged tanks may be refused','Paint colors on screen may differ from actual mixed results','Special orders may be non-returnable; confirm before purchase','Delivery availability and fees vary by location and order size']::text[],false,false,false,ARRAY['Do not imply licensed contracting services are provided by store staff','Do not advertise propane tank filling where only exchange is offered','Do not guarantee in-stock availability without real-time inventory verification','Pricing advertised in circulars must reflect actual in-store prices; no bait-and-switch']::text[])
